def simQ(p,d,mode):
    t=d['t']; V=d['V']; S=d['S']
    dt=t[1]-t[0]; n=len(V); Q0=d['Q'][0]
    if mode=='alg':
        K,=p; return Q0+K*(S-V)
    if mode=='tq':
        K,Tq=p; x=Q0; out=np.empty(n)
        for k in range(n):
            out[k]=x; x+=dt*(Q0+K*(S[k]-V[k])-x)/Tq
        return out
    if mode=='tm':
        K,Tm=p; Vf=V[0]; out=np.empty(n)
        for k in range(n):
            out[k]=Q0+K*(S[k]-Vf); Vf+=dt*(V[k]-Vf)/Tm
        return out
    if mode=='tqlead':  # V lag plus Q lag, same as before but with separate sum
        K,Tq,Tm=p; x=Q0; Vf=V[0]; out=np.empty(n)
        for k in range(n):
            out[k]=x; x+=dt*(Q0+K*(S[k]-Vf)-x)/Tq; Vf+=dt*(V[k]-Vf)/Tm
        return out
