        d=pd.read_csv(f); t=d.time_s.values
        V=d.voltage_pu.values; S=d.voltage_setpoint_pu.values; th=d.bus_angle_rad.values; y=d[ycol].values
        w=np.gradient(th,t)
        U={'V':V,'S':S,'w':w,'dV':np.gradient(V,t)}
        rows=[];
