def lp(u,T,dt=0.001):
    if T<=0: return u.copy()
    a=1-np.exp(-dt/T); return lfilter([a],[1,-(1-a)],u,zi=[(1-a)*u[0]])[0]
taus=[0.0,0.003,0.03,0.3,3.0]
def basis(d):
    dV=d['V']-d['V'][0]; dS=d['S']-d['S'][0]
    cols=[np.ones_like(dV)]
    for T in taus:
        cols.append(lp(dV,T)); cols.append(lp(dS,T))
    return np.column_stack(cols)
